using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Threading;using Musikbox;using MusikboxTests;
class StudioRevisionTests {
 static int count;static void Check(bool b,string t){if(!b)throw new Exception(t);count++;Console.WriteLine("OK "+t);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static Control[] Descendants(Control p){return p.Controls.Cast<Control>().SelectMany(c=>new[]{c}.Concat(Descendants(c))).ToArray();}
 static void Pump(Func<bool> done){var until=DateTime.UtcNow.AddSeconds(10);while(!done()&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(10);}Check(done(),"Dateiauswahl wird asynchron abgeschlossen");}
 [STAThread]static void Main(string[] args){string file=args[0],root=args[1];Directory.CreateDirectory(root);var original=File.ReadAllBytes(file);
  var input=new AudioInputSelection(true);input.Add(new[]{file,file},()=>{});Check(input.Songs.Count==1,"MP3Gain-Dateiauswahl entfernt Dubletten");Check(input.Songs[0].Artist=="Lainey Wilson","MP3Gain liest echte Metadaten");
  string bad=Path.Combine(root,"kein-mp3.wav");File.WriteAllText(bad,"kein MP3");bool failed=false;try{input.Add(new[]{bad},()=>{});}catch(ArgumentException){failed=true;}Check(failed&&input.Songs.Count==1,"Andere Formate aendern die vorhandene MP3Gain-Auswahl nicht");
  input.Clear();try{input.Add(new[]{file},()=>{throw new OperationCanceledException();});}catch(OperationCanceledException){}Check(input.Songs.Count==0,"Abbruch uebernimmt keine unvollstaendige MP3Gain-Auswahl");
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  using(var v=new MainView(Path.Combine(root,"layout.json"))){var c=new Controller(v,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));Call(c,"ReplaceProject",new Project(),null,true);v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1525,784);Application.DoEvents();
   var head=(Control)Field(v,"studioHeader");var nav=(Control)Field(v,"studioNavigation");var center=(Control)Field(v,"studioCenter");var right=(Control)Field(v,"studioRight");
   var libraryCard=(Control)Field(v,"libraryCard");var nowCard=(Control)Field(v,"nowCard");var tableCard=(Control)Field(v,"tableCard");
   Check(libraryCard.Height==126&&nowCard.Height==126,"Bibliothekskarte und leerer aktueller Titel sind deutlich kompakter");
   Check(tableCard.Top==136&&tableCard.Height<=113&&v.TagPane.Top==tableCard.Top,"Leere Titelliste kompakt und Metadaten auf gleicher oberer Kante");
   var title=(Label)Field(v,"nowTitle");title.Text="Ein sehr langer Titel mit mehreren Woertern fuer den Umbruch";v.RefreshStudioLibrary();Check(nowCard.Height==126&&title.Bottom<nowCard.Height&&libraryCard.Height==nowCard.Height,"Lange Titel veraendern die kompakte Kartenhoehe nicht");v.RefreshStudioNow();
   Check(head.Height==64&&v.PlayerPane.Height==72,"Kopfbereich und Player sind kompakter");Check(nav.Top==center.Top&&center.Top==right.Top&&nav.Height==center.Height&&center.Height==right.Height,"Alle drei Arbeitsbereiche beginnen und enden auf gleicher Hoehe");Check(v.Text.Contains(AppIdentity.Version)&&head.Controls["StudioVersion"].Text.StartsWith(AppIdentity.Version),"Aktuelle Buildnummer in Fenstertitel und Kopfzeile");
   Call(c,"OpenStudioModule","Audio-Werkzeuge");Application.DoEvents();var log=Descendants(v.ModuleHost).OfType<TextBox>().Single(x=>x.Name=="MP3Gain-Protokoll");Check(log.AllowDrop&&log.Parent is StudioTextSurface&&log.BorderStyle==BorderStyle.None,"MP3Gain-Protokoll ist eine Studio-Flaeche mit aktivem Dateidrop");
   var buttons=Descendants(v.ModuleHost).OfType<FlowLayoutPanel>().First();Check(buttons.AutoSize&&buttons.Height<120,"Werkzeugleiste nutzt nur die erforderliche Hoehe");
   int imports=0;v.PathsDropped+=(paths,index)=>imports++;
   var data=new DataObject(DataFormats.FileDrop,new[]{file});var pt=log.PointToScreen(new Point(20,20));var drag=new DragEventArgs(data,0,pt.X,pt.Y,DragDropEffects.Copy,DragDropEffects.Copy);
   typeof(Control).GetMethod("OnDragDrop",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(log,new object[]{drag});Pump(()=>!(bool)Field(c,"busy"));
   var queued=(AudioInputSelection)Field(c,"gainInputs");Check(queued.Songs.Count==1&&log.Text.Contains("1 MP3-Dateien"),"Ablegen im MP3Gain-Feld waehlt genau diese Datei fuer MP3Gain aus");Check(imports==0&&((Project)Field(c,"p")).Folders.Count==0&&v.Songs.Rows.Count==0,"MP3Gain-Drop laeuft nicht durch Bibliotheksimport oder Ordnernummerierung");Check(Application.OpenForms.Count==1,"Beim MP3Gain-Drop erscheint kein Import-Hinweisfenster");
   typeof(Control).GetMethod("OnDragDrop",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(log,new object[]{drag});Pump(()=>!(bool)Field(c,"busy"));Check(queued.Songs.Count==1,"Wiederholtes Ablegen erzeugt keine Dubletten");
   Check(original.SequenceEqual(File.ReadAllBytes(file)),"Dateiauswahl veraendert die MP3-Quelldatei nicht");
   using(var b=new Bitmap(v.ClientSize.Width,v.ClientSize.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(v.PointToScreen(Point.Empty),Point.Empty,b.Size);b.Save(Path.Combine(root,"Audio-Werkzeuge-v0.54.png"));}
   Call(c,"OpenStudioModule","Konvertierung");Application.DoEvents();var conversionLog=Descendants(v.ModuleHost).OfType<TextBox>().Single(x=>x.Name=="Konvertierungs-Dateien");var convertPoint=conversionLog.PointToScreen(new Point(20,20));
   var conversionData=new DataObject(DataFormats.FileDrop,new[]{Path.ChangeExtension(file,".wav")});var convertDrag=new DragEventArgs(conversionData,0,convertPoint.X,convertPoint.Y,DragDropEffects.Copy,DragDropEffects.Copy);typeof(Control).GetMethod("OnDragDrop",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(conversionLog,new object[]{convertDrag});Pump(()=>!(bool)Field(c,"busy"));
   Check(((AudioInputSelection)Field(c,"conversionInputs")).Songs.Count==1&&conversionLog.Text.Contains("1 Audiodateien"),"Konvertierungsdrop waehlt auch WAV-Dateien direkt fuer die Konvertierung aus");Check(imports==0&&((Project)Field(c,"p")).Folders.Count==0&&Application.OpenForms.Count==1,"Konvertierungsdrop erzeugt weder Bibliotheksordner noch Nummerierungshinweis");Check(((AudioInputSelection)Field(c,"gainInputs")).Songs.Count==1,"Werkzeugauswahlen bleiben beim Modulwechsel getrennt erhalten");
   v.SelectStudioPage("Bibliothek");// A separate routing probe avoids invoking the real importer.
   typeof(Controller).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,false);v.Close();
  }
  using(var v=new MainView(Path.Combine(root,"routing.json"))){v.Show();int library=0,module=0;var area=new Panel();v.PathsDropped+=(a,b)=>library++;v.ShowModule(area,a=>module++);v.ReceiveFileDrop(area,new[]{file},-1);v.SelectStudioPage("Bibliothek");v.ReceiveFileDrop(v.Songs,new[]{file},-1);Check(module==1&&library==1,"Bibliotheksdrop bleibt nach dem Modulwechsel erhalten");v.Close();}
  using(var report=new StudioReportView("MP3Gain-Analyse abgeschlossen","Titelanalyse\r\nLainey Wilson – 4x4xU")){report.Show();Application.DoEvents();Check(report.Text.Contains(AppIdentity.Version)&&report.Body.Content.BorderStyle==BorderStyle.None,"Bericht mit aktuellem Fenstertitel und Studio-Protokollflaeche");Check(report.AcceptButton is StudioActionButton&&report.CancelButton==report.AcceptButton,"Bericht schliesst ueber Studio-Schaltflaeche und Escape");using(var b=new Bitmap(report.Width,report.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(report.Location,Point.Empty,b.Size);b.Save(Path.Combine(root,"Studio-Bericht-v0.54.png"));}report.Close();}
  using(var message=new MessageView("Testfrage","Bestaetigung",MessageBoxButtons.YesNo,MessageBoxIcon.Question)){message.Show();Application.DoEvents();Check(message.AcceptButton is StudioActionButton&&message.CancelButton is StudioActionButton,"Bestaetigungen verwenden Studio-Schaltflaechen");message.Close();Check(message.DialogResult==DialogResult.No,"Schliessen einer Ja-Nein-Frage behaelt Nein-Semantik");}
  Console.WriteLine("BESTANDEN: "+count+" Modul-/Layout-/Dialogpruefungen; UI unter Mono/Xvfb, keine echte Windows-Abnahme.");
 }
}
